20: function serveStatic(req, res) {
21:   let urlPath;
22:   try { urlPath = decodeURIComponent(req.url.split('?')[0]); } catch { urlPath = '/'; }
23:   if (urlPath === '/') urlPath = '/index.html';
24:   const file = path.normalize(path.join(ROOT, urlPath));
25:   if (!file.startsWith(ROOT + path.sep)) { res.writeHead(403); res.end('Forbidden'); return; }
26:   fs.stat(file, (err, stat) => {
27:     if (err || !stat.isFile()) { res.writeHead(404); res.end('Not found'); return; }
28:     res.writeHead(200, {
29:       'Content-Type': MIME[path.extname(file)] || 'application/octet-stream',
30:       'Content-Length': stat.size,
31:       'Cache-Control': 'no-cache'
32:     });
33:     fs.createReadStream(file).pipe(res);
34:   });
35: }
