import json, re

# --- Load source data -------------------------------------------------------
old_premium = json.load(open('/tmp/opencode/old_premium.json'))
extra = json.load(open('/tmp/opencode/extra.json'))
genres = json.load(open('/home/runner/work/Tvgrid/Tvgrid/genres.json'))

CATEGORY_RANGES = [
    (71, 75, 'Cartoons'), (76, 80, 'Anime'), (81, 81, 'Kids'),
    (82, 82, 'Family'), (83, 88, 'Sitcoms'), (89, 91, 'Soaps'),
    (92, 94, 'Drama'), (95, 95, 'Movies'), (96, 96, 'Teen'),
    (97, 100, 'Sci-Fi'), (101, 104, 'Action'), (105, 105, 'Drama'),
    (106, 108, 'Game Shows'), (109, 110, 'Talk'), (111, 114, 'News'),
    (115, 115, 'Documentary'), (116, 116, 'Nature'), (117, 117, 'Science'),
    (118, 118, 'History'), (119, 119, 'True Crime'), (120, 120, 'Documentary'),
    (121, 121, 'History'), (122, 133, 'Movies'), (134, 135, 'Music'),
    (136, 136, 'Movies'), (137, 138, 'Sports'), (139, 140, 'Wrestling'),
]

def category_for(number):
    for lo, hi, name in CATEGORY_RANGES:
        if lo <= number <= hi:
            return name
    return 'Premium'

def year_in_text(title):
    return [int(y) for y in re.findall(r'\b(19\d\d|20\d\d)\b', str(title))]

def explicit_year_bad(item):
    y = item.get('year')
    try:
        y = int(str(y)[:4]) if y not in (None, '') else 0
    except Exception:
        y = 0
    if y and (y < 1990 or y > 2009):
        return True
    return any(v < 1990 or v > 2009 for v in year_in_text(item.get('title', '')))

def derive_year(item):
    if item.get('year'):
        return item
    ys = [v for v in year_in_text(item.get('title', '')) if 1990 <= v <= 2009]
    if ys:
        item['year'] = str(ys[0])
    return item

# --- Base premium: restore the stronger 70-channel 90s/2000s catalog --------
for channel in old_premium:
    channel['lineupCategory'] = category_for(channel['number'])
    for item in channel.get('items', []):
        derive_year(item)
json.dump(old_premium, open('/tmp/opencode/premium_clean.json', 'w'), indent=2)
with open('/home/runner/work/Tvgrid/Tvgrid/premium.js', 'w') as f:
    f.write('window.PREMIUM_CHANNELS = ' + json.dumps(old_premium, indent=2) + ';\n')

# --- Plus packs: keep only clearly 90s/2000s English-language programs ------
NON_ENGLISH = re.compile(
    r'009-1\s*\[EN SUB\]|X/1999 The Movie.*Subs|Amulet 1991.*English subtitles',
    re.I,
)
removed = []
for channel in extra:
    kept = []
    for item in channel.get('items', []):
        if explicit_year_bad(item) or NON_ENGLISH.search(item.get('title', '')):
            removed.append((channel['number'], item.get('title', '')))
            continue
        kept.append(derive_year(item))
    channel['items'] = kept

# Every plus channel should still have at least two playable programs. If a
# channel is short, borrow a valid 90s/2000s item from the base catalog.
base_items = [item for channel in old_premium for item in channel.get('items', [])]
used_ids = {item.get('id') for channel in extra for item in channel.get('items', [])}
for channel in extra:
    for item in base_items:
        if len(channel['items']) >= 2:
            break
        if item.get('id') in used_ids or explicit_year_bad(item):
            continue
        channel['items'].append(dict(item))
        used_ids.add(item.get('id'))

json.dump(extra, open('/tmp/opencode/extra_clean.json', 'w'), indent=2)
with open('/home/runner/work/Tvgrid/Tvgrid/premium_extra.js', 'w') as f:
    f.write('window.EXTRA_CHANNELS = ' + json.dumps(extra, indent=2) + ';\n')

# --- Genre channels: remove pre-90s programs and top up to three ------------
replacements = {
    55: ['Top of the Heap (1991) sitcom 7 eps, Matt Leblanc'],
    58: ['Fudge (1995) sitcom', 'Two of a Kind (1998–99) MaryKate + Ashley Olsen'],
    60: ['Now And Again (1999-2000) -all 22 eps - H.Matarazzo',
         'Perversions Of Science Complete TV Series HBO (1997) SPACE TV'],
    61: ['Lightning Force - 6: The Last Nazi'],
    62: ['Moon Over Miami (1993) crime drama'],
    67: ["Hockey - Brian Kilrea's Last Regular Season Game Coaching the OHL Ottawa 67s 15 March 2009"],
}
description_updates = {
    'genre-retro-sitcoms': '90s and 2000s sitcoms and comfort-TV comedy.',
    'genre-comedy-vault': 'British and American comedy series from the 90s and 2000s.',
    'genre-family-comedy': 'Family sitcoms and wholesome comedy from the 90s and 2000s.',
    'genre-sci-fi-theater': 'Science fiction series and speculative television from the 90s and 2000s.',
    'genre-action-zone': 'Superheroes, action and adventure series from the 90s and 2000s.',
    'genre-retro-drama': 'Drama series and television movies from the 90s and 2000s.',
    'genre-sports-archive': 'Classic sports broadcasts from the 90s and 2000s.',
}
by_title = {item.get('title'): item for item in base_items}
used_genre_ids = {item.get('id') for channel in genres for item in channel.get('items', [])}
for channel in genres:
    channel['items'] = [item for item in channel.get('items', []) if not explicit_year_bad(item)]
    channel['description'] = description_updates.get(channel['id'], channel['description'])
    for title in replacements.get(int(channel['id'].split('-')[-1]) if False else 0, []):
        pass

# The replacement map is keyed by channel number, not genre id.
number_by_id = {channel['id']: i + 55 for i, channel in enumerate(genres)}
for channel in genres:
    number = number_by_id[channel['id']]
    for title in replacements.get(number, []):
        item = by_title.get(title)
        if not item:
            raise SystemExit(f'missing replacement: {title}')
        if item.get('id') in used_genre_ids:
            continue
        channel['items'].append(dict(item))
        used_genre_ids.add(item.get('id'))

json.dump(genres, open('/home/runner/work/Tvgrid/Tvgrid/genres.json', 'w'), indent=2, ensure_ascii=False)

print('base premium channels:', len(old_premium), 'items:', sum(len(c['items']) for c in old_premium))
print('extra channels:', len(extra), 'items:', sum(len(c['items']) for c in extra), 'removed:', len(removed))
for n, title in removed:
    print('  removed', n, title)
for channel in genres:
    print('genre', number_by_id[channel['id']], channel['name'], len(channel['items']))

