import json, re, urllib.request, concurrent.futures

PATH = '/tmp/opencode/extra_current.json'
E = json.load(open(PATH))
items = [it for c in E for it in c['items'] if not it.get('year')]
print('items without year:', len(items), flush=True)

def fetch(it):
    try:
        req = urllib.request.Request(
            'https://archive.org/metadata/' + it['id'],
            headers={'User-Agent': 'Tvgrid data audit'},
        )
        with urllib.request.urlopen(req, timeout=30) as r:
            m = json.load(r)
        md = m.get('metadata', {})
        for key in ('year', 'date', 'publicdate'):
            value = md.get(key)
            if isinstance(value, list):
                value = value[0] if value else ''
            match = re.search(r'\b(19\d\d|20\d\d)\b', str(value or ''))
            if match:
                return it['id'], int(match.group(1)), key, str(value)
        return it['id'], None, None, ''
    except Exception as exc:
        return it['id'], None, 'error', str(exc)

resolved = {}
with concurrent.futures.ThreadPoolExecutor(max_workers=12) as pool:
    for ident, year, key, raw in pool.map(fetch, items):
        resolved[ident] = {'year': year, 'source': key, 'raw': raw}
        print(ident, year, key, raw[:60], flush=True)

json.dump(resolved, open('/tmp/opencode/resolved_years.json', 'w'), indent=2)
valid = sum(1 for v in resolved.values() if v['year'] and 1990 <= v['year'] <= 2009)
bad = [(k, v) for k, v in resolved.items() if v['year'] and not (1990 <= v['year'] <= 2009)]
missing = [k for k, v in resolved.items() if not v['year']]
print('resolved valid:', valid, 'out of range:', len(bad), 'unresolved:', len(missing), flush=True)
for k, v in bad:
    print('BAD', k, v, flush=True)

