// duplicate ids across base and extra
const base = window.PREMIUM_CHANNELS||[], extra = window.EXTRA_CHANNELS||[];
const seen = new Map();
let dup=0;
for (const c of base.concat(extra)) for (const it of (c.items||[])) {
  if (seen.has(it.id)) dup++; else seen.set(it.id, c.number);
}
console.log('unique item ids:', seen.size, 'repeated item ids:', dup);
EOF

